interface User {
  id: number
  name: string
  isActive: boolean
}

interface UserStatsProps {
  users: User[]
}

export default function UserStats({ users }: UserStatsProps) {
  const activeUsers = users.filter((user) => user.isActive).length
  const inactiveUsers = users.length - activeUsers
  const activePercentage = users.length > 0 ? (activeUsers / users.length) * 100 : 0

  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active Users: {activeUsers} (Active users count: {activeUsers})</p>
      <p>Inactive Users: {inactiveUsers} (Inactive users count: {inactiveUsers})</p>
      <p>Percentage of active users: {activePercentage.toFixed(2)}% (Active Percentage: {Math.round(activePercentage)}%)</p>
    </div>
  )
}

